pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        // keep caller wide but non-zero to be meaningful
        vm.assume(caller != address(0));

        // The general rule: reference contract's owner() must equal the stored owner (set at construction to address(this) in setUp)
        // We observe owner() via the public getter. For the reference this equals address(this) (the deployer passed in constructor).
        // The mutant mangles the returned owner; for some caller addresses the return will differ. We only need to call the getter.

        // We optionally impersonate the fuzzed caller to show variety of callers (not strictly needed for getter but exercises view calling context)
        vm.prank(caller);
        address observed = c.owner();

        // Exact one assertion: owner() should equal the originally stored owner (which we passed as address(this) when deploying c)
        assertTrue(observed == address(this));
    }
}

