pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // General rule: for any caller, owner() returns the stored owner address (the deployer/address set in constructor).
    // The mutant returns msg.sender instead, so for some callers the return will differ.
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero-address corner which is still admissible; no need to restrict
        // ensure caller is not this contract to allow difference (fuzzer may supply same address)
        vm.assume(caller != address(0));

        // call owner() as the fuzzed caller
        bool ok;
        address reported;
        // perform external call as caller
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            reported = o;
        } catch {
            ok = false;
            reported = address(0);
        }

        // The reference contract always returns the stored owner (the deployer, which in setUp is address(this)).
        // So for all callers the call must succeed and reported == address(this).
        // The mutant will return caller instead, so there exists some caller (the fuzzer will find) where reported != address(this).
        assertTrue(ok && reported == address(this));
    }
}

