pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test checks the universal property:
// For any caller (EOA or contract) invoking c.owner(), the returned value equals the stored owner (deployer).
// The mutant that returns tx.origin will return a different value for some contract-callers (where tx.origin != deployer)
// and therefore the test will fail on the mutant for some fuzzed caller address.

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzedParam is an arbitrary address that the fuzzer will try; we use it as the caller of owner().
    function testFuzz_property(address fuzzedCaller) public {
        // Keep domain wide: exclude the zero address to avoid degenerate cases (still wide).
        vm.assume(fuzzedCaller != address(0));

        // Deploy an intermediate caller contract that will forward a call to c.owner().
        // We pass fuzzedCaller as the tx.origin by making fuzzedCaller an EOA that calls the Forwarder.
        Forwarder forwarder = new Forwarder(address(c));

        // Give fuzzedCaller some ETH so it can call the forwarder if needed.
        vm.deal(fuzzedCaller, 1 ether);

        // Have the fuzzedCaller externally call the forwarder, which in turn calls c.owner() and returns the value.
        vm.prank(fuzzedCaller);
        address returnedOwner = forwarder.readOwner();

        // The reference contract stores the deployer (this test contract) as owner set in constructor.
        address expectedOwner = c.owner(); // call directly to read stored owner from the contract

        // The universal property: for any caller invoking through an intermediate contract, owner() returns the stored owner.
        // This holds for the reference implementation for all fuzzedCaller values, but the mutant (which returns tx.origin)
        // will return fuzzedCaller (tx.origin) instead of expectedOwner when fuzzedCaller != expectedOwner.
        assertTrue(returnedOwner == expectedOwner);
    }
}

// Minimal helper that forwards a call to C.owner() and returns the resulting address.
contract Forwarder {
    C immutable target;
    constructor(address _target) {
        target = C(_target);
    }

    function readOwner() external returns (address) {
        // forward the external call to target.owner() so that tx.origin is preserved as the original EOA caller
        return target.owner();
    }
}

