        CallerProxy proxy = new CallerProxy(address(c));

        // fund the caller EOA so it can make a call
        vm.deal(caller, 1 ether);

        // Have the EOA 'caller' externally call the proxy which will in turn call c.owner()
        vm.prank(caller);
        bytes memory ret = proxy.callOwner();

        // decode returned address
        address returned = abi.decode(ret, (address));

        // The reference implementation always returns the stored owner (the deployer: address(this) at setUp)
        // when owner() completes. The mutant returns tx.origin instead, which equals the fuzzed 'caller' here
        // only for some inputs; we assert that the returned owner equals the original deployer address.
